solution.solution.cpp:
#include <map>
#include <optional>
#include <sstream>
#include <string>
#include <vector>

std::string normalise(const std::string& line, std::map<std::string, std::string>& ids)
{
    std::istringstream in{ line };
    std::string token, out;
    bool first{ true };
    while (in >> token)
    {
        if (first && token.size() >= 3 && token.front() == '+' && token.size() > 2 && token.compare(token.size() - 2, 2, "ms") == 0)
        {
            first = false;
            continue;
        }
        first = false;
        if (token.rfind("id=", 0) == 0)
        {
            const std::string value{ token.substr(3) };
            auto it{ ids.find(value) };
            if (it == ids.end()) it = ids.emplace(value, "#" + std::to_string(ids.size() + 1)).first;
            token = "id=" + it->second;
        }
        if (!out.empty()) out += ' ';
        out += token;
    }
    return out;
}

std::optional<std::string> firstDifference(const std::vector<std::string>& golden, const std::vector<std::string>& actual)
{
    std::map<std::string, std::string> goldenIds, actualIds;
    const std::size_t n{ golden.size() > actual.size() ? golden.size() : actual.size() };
    for (std::size_t i{ 0 }; i < n; ++i)
    {
        const std::string where{ "line " + std::to_string(i + 1) + ": " };
        if (i >= actual.size()) return where + "expected \"" + normalise(golden[i], goldenIds) + "\", got end of transcript";
        if (i >= golden.size()) return where + "expected end of transcript, got \"" + normalise(actual[i], actualIds) + "\"";
        const std::string g{ normalise(golden[i], goldenIds) }, a{ normalise(actual[i], actualIds) };
        if (g != a) return where + "expected \"" + g + "\", got \"" + a + "\"";
    }
    return std::nullopt;
}

unitTests:
TEST("normalising lines") {
    std::map<std::string, std::string> ids;
    CHECK_EQ(normalise("+12ms c>s REQUEST id=41 method=open path=a.md", ids), std::string("c>s REQUEST id=#1 method=open path=a.md"));
    CHECK_EQ(normalise("+15ms s>c RESPONSE id=41 ok", ids), std::string("s>c RESPONSE id=#1 ok"));
    CHECK_EQ(normalise("+16ms c>s REQUEST   id=42 method=close", ids), std::string("c>s REQUEST id=#2 method=close"));
    CHECK_EQ(normalise("s>c EVENT saved count=+3ms", ids), std::string("s>c EVENT saved count=+3ms"));
}
TEST("matching sessions with different ids and times") {
    const std::vector<std::string> golden{ "+0ms c>s REQUEST id=1 method=open", "+3ms s>c RESPONSE id=1 ok" };
    const std::vector<std::string> actual{ "+0ms c>s REQUEST id=900 method=open", "+9ms s>c RESPONSE id=900 ok" };
    CHECK(!firstDifference(golden, actual).has_value());
}
TEST("reporting the first difference") {
    const std::vector<std::string> golden{ "+0ms c>s REQUEST id=1 method=open", "+3ms s>c RESPONSE id=1 ok" };
    const std::vector<std::string> wrongId{ "+0ms c>s REQUEST id=7 method=open", "+3ms s>c RESPONSE id=8 ok" };
    CHECK_EQ(firstDifference(golden, wrongId).value_or(""), std::string("line 2: expected \"s>c RESPONSE id=#1 ok\", got \"s>c RESPONSE id=#2 ok\""));
    const std::vector<std::string> shorter{ "+0ms c>s REQUEST id=1 method=open" };
    CHECK_EQ(firstDifference(golden, shorter).value_or(""), std::string("line 2: expected \"s>c RESPONSE id=#1 ok\", got end of transcript"));
    CHECK_EQ(firstDifference(shorter, golden).value_or(""), std::string("line 2: expected end of transcript, got \"s>c RESPONSE id=#1 ok\""));
}

